def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty) sorted by price desc, then arrival_time asc
    sell_book = []  # list of (price, arrival_time, id, qty) sorted by price asc, then arrival_time asc
    order_map = {}  # id -> (side, price, qty, arrival_time) for resting orders
    arrival_time = 0

    def match_buy(buy_id, buy_price, buy_qty, is_market):
        nonlocal trades, sell_book, order_map, buy_qty

        while buy_qty > 0 and sell_book:
            if not is_market and sell_book[0][0] > buy_price:
                break

            sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
            trade_qty = min(buy_qty, sell_qty)
            trades.append([buy_id, sell_id, sell_price, trade_qty])

            buy_qty -= trade_qty
            sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

            if sell_book[0][3] == 0:
                sell_book.pop(0)
                if sell_id in order_map:
                    del order_map[sell_id]
            else:
                if sell_id in order_map:
                    order_map[sell_id] = (order_map[sell_id][0], order_map[sell_id][1], sell_qty - trade_qty, order_map[sell_id][3])

        return buy_qty

    def match_sell(sell_id, sell_price, sell_qty, is_market):
        nonlocal trades, buy_book, order_map, sell_qty

        while sell_qty > 0 and buy_book:
            if not is_market and buy_book[0][0] < sell_price:
                break

            buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
            trade_qty = min(sell_qty, buy_qty)
            trades.append([buy_id, sell_id, buy_price, trade_qty])

            sell_qty -= trade_qty
            buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

            if buy_book[0][3] == 0:
                buy_book.pop(0)
                if buy_id in order_map:
                    del order_map[buy_id]
            else:
                if buy_id in order_map:
                    order_map[buy_id] = (order_map[buy_id][0], order_map[buy_id][1], buy_qty - trade_qty, order_map[buy_id][3])

        return sell_qty

    for order in orders:
        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, qty, arr_time = order_map[cancel_id]
                del order_map[cancel_id]
                if side == 'buy':
                    buy_book = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != cancel_id]
                else:
                    sell_book = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != cancel_id]

        elif order[0] == 'limit':
            order_type, order_id, side, price, qty = order
            remaining_qty = qty

            if side == 'buy':
                remaining_qty = match_buy(order_id, price, remaining_qty, False)
                if remaining_qty > 0:
                    buy_book.append((price, arrival_time, order_id, remaining_qty))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    order_map[order_id] = (side, price, remaining_qty, arrival_time)
            else:
                remaining_qty = match_sell(order_id, price, remaining_qty, False)
                if remaining_qty > 0:
                    sell_book.append((price, arrival_time, order_id, remaining_qty))
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    order_map[order_id] = (side, price, remaining_qty, arrival_time)

            arrival_time += 1

        elif order[0] == 'ioc':
            order_type, order_id, side, price, qty = order
            remaining_qty = qty

            if side == 'buy':
                remaining_qty = match_buy(order_id, price, remaining_qty, False)
            else:
                remaining_qty = match_sell(order_id, price, remaining_qty, False)

            arrival_time += 1

        elif order[0] == 'market':
            order_type, order_id, side, qty = order
            remaining_qty = qty

            if side == 'buy':
                remaining_qty = match_buy(order_id, float('inf'), remaining_qty, True)
            else:
                remaining_qty = match_sell(order_id, 0, remaining_qty, True)

            arrival_time += 1

    return trades

